UPDATE ifj_task
SET retired = TRUE,
    retired_time = #{retiredTime},
    update_time = #{retiredTime}
WHERE id = #{taskId}
  AND retired = FALSE
  AND retired_time IS NULL
  AND current_task_definition_id <=> #{expectedDefinitionId}
  AND current_revision <=> #{expectedRevision}

UPDATE ifj_task
SET retired = TRUE,
    retired_time = #{retiredTime},
    update_time = #{retiredTime}
WHERE id = #{taskId}
  AND retired = FALSE
  AND retired_time IS NULL
  AND current_task_definition_id IS NOT DISTINCT FROM #{expectedDefinitionId}
  AND current_revision IS NOT DISTINCT FROM #{expectedRevision}

UPDATE ifj_task
SET retired = TRUE,
    retired_time = #{retiredTime},
    update_time = #{retiredTime}
WHERE id = #{taskId}
  AND retired = FALSE
  AND retired_time IS NULL
  AND current_task_definition_id IS #{expectedDefinitionId}
  AND current_revision IS #{expectedRevision}
